    'ui_small_10': '\u041c\u0430\u043b\u044a\u043a (-10%)',
    'ui_stalker_mag_portals_authenticate_by_mac': 'Stalker/MAG \u043f\u043e\u0440\u0442\u0430\u043b\u0438\u0442\u0435 \u0441\u0435 \u0443\u0434\u043e\u0441\u0442\u043e\u0432\u0435\u0440\u044f\u0432\u0430\u0442 \u0447\u0440\u0435\u0437 MAC \u0430\u0434\u0440\u0435\u0441. \u041f\u043e\u0432\u0435\u0447\u0435\u0442\u043e \u0438\u043c\u0430\u0442 \u043d\u0443\u0436\u0434\u0430 \u0441\u0430\u043c\u043e \u043e\u0442 MAC; \u043d\u044f\u043a\u043e\u0438 \u0438\u0437\u0438\u0441\u043a\u0432\u0430\u0442 \u0441\u044a\u0449\u043e \u0441\u0435\u0440\u0438\u0435\u043d \u043d\u043e\u043c\u0435\u0440 \u0438 ID \u043d\u0430 \u0443\u0441\u0442\u0440\u043e\u0439\u0441\u0442\u0432\u043e \u2014 \u043e\u0441\u0442\u0430\u0432\u0435\u0442\u0435 \u0433\u0438 \u043f\u0440\u0430\u0437\u043d\u0438, \u043e\u0441\u0432\u0435\u043d \u0430\u043a\u043e \u0434\u043e\u0441\u0442\u0430\u0432\u0447\u0438\u043a\u044a\u0442 \u0432\u0438 \u0433\u0438 \u0435 \u043f\u0440\u0435\u0434\u043e\u0441\u0442\u0430\u0432\u0438\u043b.',
